// VIOLATION: Only handles populated state
function UserList() {
  const { data: users } = useUsers()
  return (
    <ul>
      {users.map(u => <li key={u.id}>{u.name}</li>)}
    </ul>
  )
  // Missing: loading, empty, error, overflow
}

// CORRECT: All states handled
function UserList() {
  const { data: users, isLoading, error } = useUsers()

  if (isLoading) return <UserListSkeleton />
  if (error) return <ErrorState message="Couldn't load users" onRetry={refetch} />
  if (!users?.length) return <EmptyState title="No users yet" cta="Invite your team" />

  return (
    <VirtualList items={users} estimateSize={48}>
      {user => <UserRow key={user.id} user={user} />}
    </VirtualList>
  )
}

