function ProjectList({ orgId }: { orgId: string }) {
  const {
    data, isLoading, error, fetchNextPage, hasNextPage
  } = useInfiniteProjects({ orgId, limit: 25 })  // Scoped, paginated

  if (isLoading) return <ProjectListSkeleton count={5} />
  if (error) return <ErrorState error={error} onRetry={refetch} />

  const projects = data?.pages.flatMap(p => p.items) ?? []
  if (!projects.length) {
    return <EmptyState
      title={t('projects.empty.title')}
      description={t('projects.empty.description')}
      action={{ label: t('projects.empty.cta'), onClick: openCreateDialog }}
    />
  }

  return (
    <VirtualList
      items={projects}
      onEndReached={() => hasNextPage && fetchNextPage()}
    >
      {project => (
        <ProjectCard
          key={project.id}
          project={project}
          onDelete={() => confirmDelete(project)}  // Confirmation
        />
      )}
    </VirtualList>
  )
}
